sample:
# text の dynamic ブロックが生成する ingress ルールを、
# lesson06 で学んだ for 式で「見える化」してみます。
# dynamic は書けなくても、この繰り返しロジックが読めれば十分です。

locals {
  ports = [80, 443]

  # 各ポートから "80-80/tcp" 形式のルール文字列を作る
  rules = [for p in local.ports : format("%d-%d/tcp", p, p)]
}

output "rule_count" {
  value = length(local.rules)
}

output "rules" {
  value = join(", ", local.rules)
}

exercise.starter:
variable "allowed_ports" {
  type    = list(number)
  default = [22, 80, 443]
}

# ここに locals(for 式)と output を書く

exercise.answer:
variable "allowed_ports" {
  type    = list(number)
  default = [22, 80, 443]
}

# dynamic "ingress" { for_each = var.allowed_ports ... } と同じ繰り返しです。
# dynamic が port の数だけ content を生成するのと同様に、
# for 式は要素の数だけルール文字列を生成します。
locals {
  rules = [for p in var.allowed_ports : format("%d-%d/tcp", p, p)]
}

output "rules" {
  value = join(", ", local.rules)
}
